package com.formation.loan.service;
import com.formation.loan.client.BookClient; import com.formation.loan.dto.*; import com.formation.loan.exception.LoanException; import com.formation.loan.model.*; import com.formation.loan.repository.LoanRepository; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.InjectMocks; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import java.util.Optional; import static org.junit.jupiter.api.Assertions.assertThrows; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class LoanServiceTest { @Mock LoanRepository repository; @Mock BookClient books; @InjectMocks LoanService service; @Test void exhaustedBookDoesNotDecrement(){when(repository.countByMemberNameIgnoreCaseAndStatusAndDeletedFalse(anyString(),eq(LoanStatus.ACTIVE))).thenReturn(0L);when(books.findById(3L)).thenReturn(new BookDto(3L,"Livre","Auteur","isbn",1,0));assertThrows(LoanException.class,()->service.create(new LoanRequest("Bob",3L)));verify(books,never()).decrement(3L);} @Test void createUsesReadThenWrite(){when(repository.countByMemberNameIgnoreCaseAndStatusAndDeletedFalse(anyString(),eq(LoanStatus.ACTIVE))).thenReturn(0L);when(books.findById(3L)).thenReturn(new BookDto(3L,"Livre","Auteur","isbn",1,1));when(repository.save(any())).thenAnswer(i->i.getArgument(0));var result=service.create(new LoanRequest(" Bob ",3L));verify(books).decrement(3L);org.junit.jupiter.api.Assertions.assertEquals(java.time.LocalDate.now().plusDays(14),result.dueDate());} }
